#include <stdio.h>
#include <string.h>

int main() {
    int sum, n;
    scanf("%d %d", &sum, &n);

    int mid = sum / n;

    int left, right, half;

    if(n % 2 == 0) {
        half = n / 2;
        left = mid - half + 1;
    } else {
        half = (n - 1) / 2;
        left = mid - half;
    }

    right = mid + half;

    char res[100000];

    int total = 0;
    for(int i = left; i <= right; i++) {
        char tmp[1000];
        sprintf(tmp, "%d", i);
        strcat(res, tmp);

        if(i < right) {
            strcat(res, " ");
        }

        total += i;
    }

    if(total == sum) {
        puts(res);
    } else {
        puts("-1");
    }

    return 0;
}
